import { CommonModule } from '@angular/common';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { RouterModule } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ApiService, Education } from '../../../../services/api';
import { Observable, Subscription } from 'rxjs';

@Component({
  selector: 'app-learning',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslateModule],
  templateUrl: './learning.component.html',
  styleUrl: './learning.component.css'
})
export class LearningComponent implements OnInit, OnDestroy {
  showFullProjects = false;
  $education: Observable<Education[]> = new Observable();
  private langChangeSubscription?: Subscription;

  constructor(
    private translate: TranslateService,
    private apiService: ApiService
  ) {}

  ngOnInit() {
    this.loadEducation();

    // Recargar cuando el idioma cambie
    this.langChangeSubscription = this.translate.onLangChange.subscribe(() => {
      this.loadEducation();
    });
  }

  ngOnDestroy() {
    if (this.langChangeSubscription) {
      this.langChangeSubscription.unsubscribe();
    }
  }

  loadEducation() {
    this.$education = this.apiService.getEducation();
  }

  toggleFullProjects() {
    this.showFullProjects = !this.showFullProjects;
  }

  changeLang(language: string) {
    this.translate.use(language);
  }
}
<section id="learning-section">
  <div class="learning-card">
    <h2>{{ 'LEARNING.TITLE' | translate }}</h2>

    <div *ngFor="let edu of $education | async" class="learning-item">
      <div class="education-item">
        <h3>
          {{ edu.institution }}
          <span class="dates">{{ edu.period }}</span>
        </h3>
        <p>{{ edu.degree }}</p>
      </div>
    </div>
  </div>
</section>
